<?php
require_once __DIR__.'/../../auth/auth_check.php';require_once __DIR__.'/../../config/database.php';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){$nama=trim($_POST['nama_perusahaan']??'');$izin=trim($_POST['nomor_izin']??'');if($nama&&$izin){$st=$pdo->prepare('INSERT INTO reklamasi_hutan (nama_perusahaan,nomor_izin,luas_lahan,lokasi_reklamasi,jenis_tanaman,tahun_kegiatan,persentase_penyelesaian,status_reklamasi) VALUES (?,?,?,?,?,?,?,?)');$st->execute([$nama,$izin,(float)($_POST['luas_lahan']??0),$_POST['lokasi_reklamasi']??'',$_POST['jenis_tanaman']??'',(int)($_POST['tahun_kegiatan']??date('Y')),(int)($_POST['persentase']??0),$_POST['status_reklamasi']??'Diajukan']);header('Location: index.php');exit;}else{$error='Nama perusahaan dan nomor izin wajib diisi.';}}
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Reklamasi Hutan | SICERDAS</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css" rel="stylesheet"><link href="../../assets/css/style.css" rel="stylesheet"></head><body><?php include __DIR__.'/../../layouts/sidebar.php';?><div class="main-wrapper"><?php include __DIR__.'/../../layouts/navbar.php';?><main class="content"><div class="page-heading"><div><p>Kegiatan Lingkungan</p><h1>Reklamasi Hutan</h1></div></div><div class="row g-3"><div class="col-lg-4"><div class="panel p-3"><h2 class="fs-6">Tambah Kegiatan</h2><?php if($error):?><div class="alert alert-danger"><?=htmlspecialchars($error)?></div><?php endif?><form method="post" class="vstack gap-2"><input class="form-control" name="nama_perusahaan" placeholder="Nama perusahaan" required><input class="form-control" name="nomor_izin" placeholder="Nomor izin" required><input type="number" step="0.01" class="form-control" name="luas_lahan" placeholder="Luas lahan (Ha)"><input class="form-control" name="lokasi_reklamasi" placeholder="Lokasi"><input class="form-control" name="jenis_tanaman" placeholder="Jenis tanaman"><input type="number" class="form-control" name="tahun_kegiatan" value="<?=date('Y')?>"><input type="number" min="0" max="100" class="form-control" name="persentase" value="0"><select class="form-select" name="status_reklamasi"><option>Diajukan</option><option>Berjalan</option><option>Selesai</option></select><button class="btn btn-orange">Simpan</button></form></div></div><div class="col-lg-8"><div class="panel table-panel"><div class="table-responsive"><table class="table sicerdas-table"><thead><tr><th>Perusahaan</th><th>Nomor Izin</th><th>Lokasi</th><th>Progres</th><th>Status</th></tr></thead><tbody><?php $rows=$pdo->query('SELECT * FROM reklamasi_hutan ORDER BY created_at DESC')->fetchAll();foreach($rows as $r):?><tr><td><?=htmlspecialchars($r['nama_perusahaan'])?></td><td><?=htmlspecialchars($r['nomor_izin'])?></td><td><?=htmlspecialchars($r['lokasi_reklamasi'])?></td><td><div class="progress"><div class="progress-bar bg-success" style="width:<?=min(100,(int)$r['persentase_penyelesaian'])?>%"></div></div><small><?= (int)$r['persentase_penyelesaian']?>%</small></td><td><?=htmlspecialchars($r['status_reklamasi'])?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="5" class="text-center py-4">Belum ada data.</td></tr><?php endif?></tbody></table></div></div></div></div></main></div><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script></body></html>
